"""Map a Mantle turn onto an A2A task state.

:meth:`MantleTaskStateMapper.map` lists the nine rules. First match wins.
A user-facing frame is a skill or ordered-block frame whose skill is not
``engine_managed``, ``hidden``, or ``disabled``. A bundled ``is_default``
skill counts only when ``include_default_skills`` is on, which is the same
skill the card advertises after a project override clears
``engine_managed``. Parked frames count. A user-facing skill that finished
this turn wins over a same-turn decline, so the orchestrator still receives
that skill's result.
This mapper does not read ``latest_action_name`` and never returns
``working``. Bearer rejection stays in the A2A auth middleware.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

from a2a.types import TaskState

from rasa.core.a2a_server.task_state_mapper import TaskStateMappingResult
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.shared.core.events import (
    BotUttered,
    SkillCompleted,
    UnsupportedRequestClassified,
)

if TYPE_CHECKING:
    from rasa.dialogue_understanding.stack.frames.dialogue_stack_frame import (
        DialogueStackFrame,
    )
    from rasa.mantle.skills.catalog import SkillCatalog
    from rasa.mantle.skills.skill import Skill
    from rasa.shared.core.trackers import DialogueStateTracker

TURN_ERROR_TYPE = "turn_error"
CONVERSATION_ENDED_ERROR_TYPE = "conversation_ended"
TURN_INCOMPLETE_ERROR_TYPE = "turn_incomplete"

_PathFrame = SkillStackFrame | OrderedBlockStackFrame


def is_user_facing_skill(
    skill: "Skill | None",
    *,
    include_default_skills: bool = False,
) -> bool:
    """Return whether *skill* is something an orchestrator is waiting on.

    ``engine_managed``, ``hidden``, and ``disabled`` skills are not offered.
    A bundled ``is_default`` skill is offered only when
    *include_default_skills* is set and a project override cleared
    ``engine_managed``; that is the skill the card advertises. A missing
    catalog entry is not user-facing either.
    """
    if skill is None:
        return False
    if skill.engine_managed or skill.hidden or skill.disabled:
        return False
    if skill.is_default and not include_default_skills:
        return False
    return True


def is_user_facing_frame(
    frame: "DialogueStackFrame",
    catalog: "SkillCatalog",
    *,
    include_default_skills: bool = False,
) -> bool:
    """Return whether *frame* is a user-facing skill or ordered block."""
    if not isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return False
    return is_user_facing_skill(
        catalog.skill_by_id(frame.skill_id),
        include_default_skills=include_default_skills,
    )


def user_facing_frames(
    tracker: "DialogueStateTracker",
    catalog: "SkillCatalog",
    *,
    include_default_skills: bool = False,
) -> list[_PathFrame]:
    """User-facing frames from the bottom of the stack to the top.

    Parked frames are included. The last item is the active user-facing frame.
    """
    return [
        frame
        for frame in tracker.stack.frames
        if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
        and is_user_facing_frame(
            frame, catalog, include_default_skills=include_default_skills
        )
    ]


def top_user_facing_frame(
    tracker: "DialogueStateTracker",
    catalog: "SkillCatalog",
    *,
    include_default_skills: bool = False,
) -> _PathFrame | None:
    """The active user-facing frame, or ``None`` when the stack has none."""
    frames = user_facing_frames(
        tracker, catalog, include_default_skills=include_default_skills
    )
    if not frames:
        return None
    return frames[-1]


class MantleTaskStateMapper:
    """Apply the nine Mantle task-state rules."""

    def __init__(
        self,
        catalog: "SkillCatalog",
        *,
        include_default_skills: bool = False,
    ) -> None:
        """Bind the catalog and whether advertised defaults are user-facing."""
        self._catalog = catalog
        self._include_default_skills = include_default_skills

    def map(
        self,
        tracker: "DialogueStateTracker",
        *,
        outcome: Any | None = None,
        orchestrator_cancel: bool = False,
    ) -> TaskStateMappingResult:
        """Return the A2A state for the tracker after this turn.

        ``outcome`` is the ``TurnResult`` recorded on the output channel.
        ``None`` means this request did not run an engine turn. A message
        after hangup is that case: the tracker is already terminated, so
        rule 4 applies. Bearer rejection does not come through here.

        Priority order:

        1. ``failed`` (``turn_error``) when the turn recorded an error
        2. ``canceled`` when the orchestrator canceled or the turn was
           cancelled
        3. on hangup, ``completed`` when a user-facing skill finished and
           the stack is empty, otherwise ``canceled``
        4. ``failed`` (``conversation_ended``) when the tracker is terminated
        5. ``completed`` when a user-facing skill finished this turn and no
           user-facing frame remains
        6. ``rejected`` when nothing user-facing remains and this turn
           classified an unsupported request
        7. ``input_required`` when a user-facing frame remains or a tool
           confirmation is pending
        8. ``completed`` when the turn succeeded and the bot spoke
        9. ``failed`` (``turn_incomplete``) otherwise

        Args:
            tracker: Tracker after the turn, or the unchanged terminated
                tracker when the processor returned before the engine.
            outcome: Engine turn result, when one was recorded.
            orchestrator_cancel: ``True`` when ``tasks/cancel`` signaled
                this turn.
        """
        error = _outcome_error(outcome)
        if error is not None:
            return TaskStateMappingResult(
                state=TaskState.TASK_STATE_FAILED,
                error_type=TURN_ERROR_TYPE,
                error_info={"message": error},
            )

        if orchestrator_cancel or _outcome_flag(outcome, "cancelled"):
            return TaskStateMappingResult(
                state=TaskState.TASK_STATE_CANCELED,
                canceled_skill=self._canceled_skill_id(tracker),
            )

        if _outcome_flag(outcome, "hangup_requested"):
            if _user_facing_skills_completed(
                tracker,
                self._catalog,
                include_default_skills=self._include_default_skills,
            ) and (not self._user_facing_frames(tracker)):
                return TaskStateMappingResult(state=TaskState.TASK_STATE_COMPLETED)
            return TaskStateMappingResult(
                state=TaskState.TASK_STATE_CANCELED,
                canceled_skill=self._canceled_skill_id(tracker),
            )

        if tracker.terminated:
            return TaskStateMappingResult(
                state=TaskState.TASK_STATE_FAILED,
                error_type=CONVERSATION_ENDED_ERROR_TYPE,
            )

        # Completion wins over a decline in the same turn. The finished
        # skill's public memory is the task result; a decline with nothing
        # finished is rejected below.
        if _user_facing_skills_completed(
            tracker,
            self._catalog,
            include_default_skills=self._include_default_skills,
        ) and (not self._user_facing_frames(tracker)):
            return TaskStateMappingResult(state=TaskState.TASK_STATE_COMPLETED)

        if not self._user_facing_frames(tracker):
            reason = _unsupported_request_type(tracker)
            if reason is not None:
                return TaskStateMappingResult(
                    state=TaskState.TASK_STATE_REJECTED,
                    reason=reason,
                )

        if self._user_facing_frames(tracker) or _pending_tool_confirmation(tracker):
            return TaskStateMappingResult(state=TaskState.TASK_STATE_INPUT_REQUIRED)

        if _turn_succeeded(outcome) and _bot_spoke(tracker):
            return TaskStateMappingResult(state=TaskState.TASK_STATE_COMPLETED)

        return TaskStateMappingResult(
            state=TaskState.TASK_STATE_FAILED,
            error_type=TURN_INCOMPLETE_ERROR_TYPE,
        )

    def _user_facing_frames(self, tracker: "DialogueStateTracker") -> list[_PathFrame]:
        """User-facing frames, using this mapper's default-skill flag."""
        return user_facing_frames(
            tracker,
            self._catalog,
            include_default_skills=self._include_default_skills,
        )

    def _canceled_skill_id(self, tracker: "DialogueStateTracker") -> str | None:
        """The skill the user was on, for this mapper's default-skill flag."""
        return _canceled_skill_id(
            tracker,
            self._catalog,
            include_default_skills=self._include_default_skills,
        )


def _outcome_error(outcome: Any | None) -> str | None:
    if outcome is None:
        return None
    error = getattr(outcome, "error", None)
    if isinstance(error, str) and error:
        return error
    return None


def _outcome_flag(outcome: Any | None, name: str) -> bool:
    if outcome is None:
        return False
    return bool(getattr(outcome, name, False))


def _turn_succeeded(outcome: Any | None) -> bool:
    """A missing outcome did not report an error, so the turn counts as clean."""
    if outcome is None:
        return True
    if _outcome_error(outcome) is not None:
        return False
    if _outcome_flag(outcome, "cancelled"):
        return False
    return True


def _user_facing_skills_completed(
    tracker: "DialogueStateTracker",
    catalog: "SkillCatalog",
    *,
    include_default_skills: bool = False,
) -> bool:
    """Whether a user-facing skill emitted ``SkillCompleted`` this turn."""
    return bool(
        completed_user_facing_skill_ids(
            tracker,
            catalog,
            include_default_skills=include_default_skills,
        )
    )


def completed_user_facing_skill_ids(
    tracker: "DialogueStateTracker",
    catalog: "SkillCatalog",
    *,
    include_default_skills: bool = False,
) -> list[str]:
    """User-facing skills that completed this turn, in event order."""
    completed: list[str] = []
    seen: set[str] = set()
    for event in tracker.get_last_turn_events():
        if not isinstance(event, SkillCompleted):
            continue
        if event.skill_id in seen:
            continue
        if not is_user_facing_skill(
            catalog.skill_by_id(event.skill_id),
            include_default_skills=include_default_skills,
        ):
            continue
        seen.add(event.skill_id)
        completed.append(event.skill_id)
    return completed


def _unsupported_request_type(tracker: "DialogueStateTracker") -> str | None:
    """Request type from the last ``UnsupportedRequestClassified`` this turn."""
    label: str | None = None
    for event in tracker.get_last_turn_events():
        if isinstance(event, UnsupportedRequestClassified):
            label = event.label
    return label


def _pending_tool_confirmation(tracker: "DialogueStateTracker") -> bool:
    value = tracker.get_slot("system.pending_tool_confirmation")
    return value is not None


def _bot_spoke(tracker: "DialogueStateTracker") -> bool:
    """Whether this turn delivered text or buttons to the user."""
    for event in tracker.get_last_turn_events():
        if not isinstance(event, BotUttered):
            continue
        if (event.text or "").strip():
            return True
        data = event.data or {}
        buttons = data.get("buttons")
        if isinstance(buttons, list) and buttons:
            return True
    return False


def _canceled_skill_id(
    tracker: "DialogueStateTracker",
    catalog: "SkillCatalog",
    *,
    include_default_skills: bool = False,
) -> str | None:
    """The user-facing skill still on the stack.

    ``tasks/cancel`` names the dropped skill on the engine result. This is
    for hangup and barge-in, which leave that skill in place.
    """
    frame = top_user_facing_frame(
        tracker, catalog, include_default_skills=include_default_skills
    )
    if frame is None:
        return None
    return frame.skill_id
